#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

long long power(long long a, long long b) {
    long long res = 1;
    a %= MOD;
    while (b > 0) {
        if (b & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

int n;
const int N = 1 << 20;
int f_arr[N], g_arr[N];
int p_table[21][21];
int idx0[N], idx1[N];
int rev_arr[N];
int matched_arr[21];
int adj_mat[21][21];

void transform(int* output, const vector<int>& left_side, const vector<int>& right_side,
               const vector<int>& subgraphs, int* index_fn) {
    vector<pair<int,int>> edge_list;
    for (int u : left_side) {
        for (int v : right_side) {
            edge_list.push_back({u, v});
        }
    }

    int edge_count = edge_list.size();
    for (int mask = 0; mask < (1 << edge_count); ++mask) {
        long long factor = 1;

        for (int i = 0; i < edge_count; ++i) {
            int u = edge_list[i].first, v = edge_list[i].second;
            if (mask & (1 << i)) {
                factor = (factor * p_table[u][v]) % MOD;
                adj_mat[u][v] = 1;
            } else {
                factor = (factor * ((1 - p_table[u][v] + MOD) % MOD)) % MOD;
                adj_mat[u][v] = 0;
            }
        }

        int new_mask = 0;
        for (int gr : subgraphs) {
            vector<int> L(left_side.begin(), left_side.end());
            vector<int> R;
            for (int i = 0; i < n; ++i) {
                if (gr & (1 << i)) R.push_back(i + n);
            }
            sort(R.begin(), R.end());

            bool found = false;
            do {
                bool ok = true;
                for (size_t i = 0; i < L.size(); ++i) {
                    if (!adj_mat[L[i]][R[i]]) { ok = false; break; }
                }
                if (ok) { found = true; break; }
            } while (next_permutation(R.begin(), R.end()));
            if (found) new_mask |= (1 << index_fn[gr]);
        }

        output[new_mask] = (output[new_mask] + static_cast<int>(factor)) % MOD;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    long long inv100 = power(100, MOD - 2);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            long long x; cin >> x;
            p_table[i][j + n] = (x * inv100) % MOD;
        }
    }

    if (n == 1) {
        cout << p_table[0][1] << '\n';
        return 0;
    }

    int half1 = n / 2;
    int half2 = n - half1;

    int cnt1 = 0, cnt2 = 0;
    vector<int> S1, S2;

    for (int mask = 0; mask < (1 << n); ++mask) {
        if (__builtin_popcount(mask) == half1) {
            idx0[mask] = cnt1;
            S1.push_back(mask);
            ++cnt1;
        }
        if (__builtin_popcount(mask) == half2) {
            idx1[mask] = cnt2;
            S2.push_back(mask);
            ++cnt2;
        }
    }

    for (int i = 0; i < cnt2; ++i) {
        int mask = S2[i];
        int comp = ((1 << n) - 1) ^ mask;
        rev_arr[i] = idx0[comp];
    }

    vector<int> L1, L2, R;
    for (int i = n; i < 2 * n; ++i) R.push_back(i);
    for (int i = 0; i < half1; ++i) L1.push_back(i);
    for (int i = half1; i < n; ++i) L2.push_back(i);

    transform(f_arr, L1, R, S1, idx0);
    transform(g_arr, L2, R, S2, idx1);

    int size1 = 1 << cnt1;
    for (int i = 0; i < cnt1; ++i) {
        for (int mask = 0; mask < size1; ++mask) {
            if (mask & (1 << i)) {
                f_arr[mask] = (f_arr[mask] + f_arr[mask ^ (1 << i)]) % MOD;
            }
        }
    }

    long long final_ans = 0;
    int size2 = 1 << cnt2;
    for (int mask = 1; mask < size2; ++mask) {
        int complement = size2 - 1 - mask;
        int rev_mask = 0;
        for (int i = 0; i < cnt2; ++i) {
            if (complement & (1 << i)) rev_mask |= (1 << rev_arr[i]);
        }

        int inv = (size1 - 1) ^ rev_mask;
        long long w = (1 - f_arr[inv] + MOD) % MOD;
        final_ans = (final_ans + w * g_arr[mask]) % MOD;
    }

    cout << final_ans << '\n';
    return 0;
}
